70:      *  Convert the string to UTF-8 
71:      *
72:      *  @param theText The string to be converted to UTF-8
73:      *  @param charSet The Code page to use in performing the conversion
74:      *
75:      *  @return the UTF-8 string
76:      */
77:     string StringToUTF8(const string &theText, CDXCharSet charSet)
78:     {
79:         // First convert to unicode using UTF-16 encoding
80:         int nWideChars = 0;
81:         UINT32 codePage;
82: 
83:         // If we were given a specific encoding, try that first (a CDX CharSet == a Windows Code Page)
84:         if (charSet != kCDXCharSetUnknown)
85:         {
86:             codePage = charSet;
87:             nWideChars = MultiByteToWideChar(codePage, MB_ERR_INVALID_CHARS, theText.data(), (int)theText.size(), 0, 0);
88:         }
89: 
90:         // If we weren't given a specific encoding or its translation failed, try using the system default codepage
91:         if (nWideChars == 0)
92:         {
93:             codePage = CP_ACP;
94:             nWideChars = MultiByteToWideChar(codePage, MB_ERR_INVALID_CHARS, theText.data(), (int)theText.size(), 0, 0);
95:         }
96: 
97:         // If we can't convert using the system default codepage, try hardcoding to ascii
98:         if (nWideChars == 0)
99:         {
100:             codePage = kCDXCharSetWin31Latin1;
101:             nWideChars = MultiByteToWideChar(codePage, MB_ERR_INVALID_CHARS, theText.data(), (int)theText.size(), 0, 0);
102:         }
103: 
104:         // We really had better have gotten something by this point
105:         ASSERT(nWideChars != 0);
106:         if (nWideChars == 0)
107:         {
108:             throw runtime_error("Text cannot be converted to Unicode");
109:         }
110: 
111:         auto_buffer<wchar_t> wide_chars(nWideChars);
112:         nWideChars = MultiByteToWideChar(codePage, MB_ERR_INVALID_CHARS, theText.data(), (int)theText.size(), wide_chars.ptr(), nWideChars);
113: 
114:         // Now convert to UTF-8
115:         string utf8 = ConvertUTF16to8(UTF16_string((UINT16*)wide_chars.ptr(), nWideChars));
116: 
117:         return utf8;
118:     }
119:     #endif // TARGET_OS_WIN32
